-- pglet's own page bound on a key (a 2 692-byte `bytea` alternating NUL with a non-zero
-- byte, `EDGES.md` row 192) stands in for no 18.6 error, so a primary key's NULL is refused
-- `23502` ahead of it — 18.6 builds that entry and answers the NULL.
-- @setup
CREATE TABLE t (a bytea);
INSERT INTO t VALUES (NULL), ('\');
-- @test
-- @expect-error: the NULL before pglet's page bound
-- @expect-message
-- @profile-lock
ALTER TABLE t ADD PRIMARY KEY (a);
